  right: 14px;
  z-index: 3;
  width: 42px;
  height: 42px;
  border: 0;
  border-radius: 12px;
  background: rgba(13, 13, 13, .06);
  color: #0d0d0d;
  font-size: 26px;
  line-height: 1;
  cursor: pointer;
}
.disc-modal__close:hover { background: rgba(13, 13, 13, .12); }

.disc-modal__head {
  padding: 26px 64px 6px;
  text-align: center;
}

.disc-modal__title {
  margin: 0 0 8px;
  font-size: clamp(22px, 3vw, 30px);
  line-height: 1.15;
  color: #0d0d0d;
}

.disc-modal__sub {
  font-size: 15px;
  color: var(--muted);
  margin-bottom: 8px;
}

.disc-modal__lead {
  display: inline-block;
  background: var(--blue-soft);
  color: #1a3f8f;
  border-radius: 10px;
  padding: 9px 16px;
  font-size: 15px;
}

.disc-modal__tabs {
  display: flex;
  flex-wrap: nowrap;
  justify-content: center;
  gap: 8px;
  padding: 16px 24px 4px;
  overflow-x: auto;
  overflow-y: hidden;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.disc-modal__tabs::-webkit-scrollbar { height: 0; }

.disc-tab {
  flex: none;
  border: 0;
  background: var(--blue-soft);
  color: #2c2c2c;
  border-radius: 10px;
  padding: 12px 16px;
  font-size: 17px;
  line-height: 1;
  cursor: pointer;
  transition: background .15s ease, color .15s ease;
}
.disc-tab:hover { background: #dcebfb; }
.disc-tab.is-active { background: var(--blue); color: #fff; }

.disc-modal__body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  padding: 14px 24px 26px;
}

.disc-pane { display: none; }
.disc-pane.is-active { display: block; }

.disc-grid3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 14px;
}

.disc-card {
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow: hidden;
  background: var(--card);
  display: flex;
  flex-direction: column;
}

.disc-card__title {
  padding: 13px 16px;
  font-size: 19px;
  font-weight: 800;
  color: #1c1c1c;
}

.disc-card__foot {
  padding: 13px 16px;
  font-size: 19px;
  font-weight: 800;
  color: #1c1c1c;
  background: #f7f9fc;
  border-top: 1px solid var(--line);
}

.disc-list {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--line);
}

.disc-item {
  position: relative;
  padding: 14px 48px 14px 16px;
  min-height: 54px;
  display: flex;
  align-items: center;
  font-size: 17px;
  color: #2c2c2c;
  background: #fff;
  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
}
.disc-item + .disc-item { border-top: 1px solid var(--line); }
.disc-item:hover { background: #f8fbff; }

.disc-item.is-dragging {
  opacity: .55;
  cursor: grabbing;
}

.disc-item.is-over {
  outline: 2px dashed rgba(31, 91, 214, .45);
  outline-offset: -6px;
}

.disc-handle {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
  opacity: .7;
}
.disc-handle:hover { opacity: 1; }
.disc-item.is-dragging .disc-handle { cursor: grabbing; }
.disc-handle svg { display: block; }

body.is-drag-active {
  cursor: grabbing;
  user-select: none;
  -webkit-user-select: none;
}

/* footer: progress + actions */
.disc-foot {
  flex: none;
  background: #fff;
  border-top: 1px solid var(--line);
  padding: 14px 24px 18px;
}

.disc-progress {
  height: 12px;
  border-radius: 999px;
  background: rgba(0, 0, 0, .08);
  overflow: hidden;
  margin-bottom: 14px;
}

.disc-progress__bar {
  height: 100%;
  width: 0;
  border-radius: 999px;
  background: var(--green);
  transition: width .25s ease;
}

.disc-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}

.disc-btn {
  border: 1px solid rgba(0, 0, 0, .22);
  border-radius: 999px;
  background: #fff;
  color: #1c1c1c;
  padding: 13px 36px;
  font-size: 18px;
  cursor: pointer;
  transition: background .15s ease;
}
.disc-btn:hover { background: #f1f3f8; }
.disc-btn--primary {
  background: var(--green);
  border-color: transparent;
  color: #fff;
}
.disc-btn--primary:hover { background: var(--green-dark); }
.disc-btn:disabled { opacity: .45; cursor: not-allowed; }

/* ============ Result ============ */
.result {
  min-height: 100vh;
  min-height: 100dvh;
  padding: 40px 20px;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  background:
    radial-gradient(1000px 500px at 100% -10%, #e2eaff 0%, rgba(226, 234, 255, 0) 60%),
    radial-gradient(900px 500px at -10% 110%, #dcf6e6 0%, rgba(220, 246, 230, 0) 60%),
    var(--bg);
}

.result__card {
  width: min(880px, 100%);
  background: var(--card);
  border-radius: 24px;
  box-shadow: 0 24px 70px rgba(0, 0, 0, .12);
  padding: clamp(24px, 5vw, 48px);
  margin-top: 16px;
}

.result__kicker {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--blue);
  margin: 0 0 6px;
}

.result__title {
  margin: 0 0 18px;
  font-size: clamp(24px, 4vw, 34px);
  letter-spacing: -0.01em;
}

.result__score {
  font-size: clamp(26px, 4.6vw, 40px);
  font-weight: 800;
  letter-spacing: .01em;
  font-variant-numeric: tabular-nums;
  margin: 0 0 6px;
}

.result__score-hint {
  color: var(--muted);
  font-size: 15px;
  margin: 0 0 26px;
}

.bars { display: grid; gap: 14px; margin-bottom: 28px; }

.bar {
  display: grid;
  grid-template-columns: 46px 1fr 64px;
  align-items: center;
  gap: 14px;
}

.bar__letter {
  font-size: 22px;
  font-weight: 800;
  text-align: center;
  border-radius: 10px;
  padding: 4px 0;
  color: #fff;
}
.bar[data-type="d"] .bar__letter { background: var(--d); }
.bar[data-type="i"] .bar__letter { background: var(--i); }
.bar[data-type="s"] .bar__letter { background: var(--s); }
.bar[data-type="c"] .bar__letter { background: var(--c); }

.bar__track {
  position: relative;
  height: 16px;
  background: #eef1f7;
  border-radius: 999px;
  overflow: hidden;
}

.bar__zero {
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 2px;
  background: #cbd5e1;
  transform: translateX(-1px);
}

.bar__fill {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 0;
  border-radius: 999px;
}
.bar[data-type="d"] .bar__fill { background: var(--d); }
.bar[data-type="i"] .bar__fill { background: var(--i); }
.bar[data-type="s"] .bar__fill { background: var(--s); }
.bar[data-type="c"] .bar__fill { background: var(--c); }

.bar__value {
  text-align: right;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  font-size: 17px;
}

.result__note {
  background: #f7f9fc;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 16px 18px;
  font-size: 15px;
  color: var(--muted);
  margin: 0 0 30px;
}
.result__note strong { color: var(--ink); }

.decode h2 {
  font-size: clamp(20px, 3vw, 26px);
  margin: 0 0 6px;
}

.decode__intro {
  color: var(--muted);
  font-size: 15px;
  margin: 0 0 18px;
}

.decode__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 14px;
  margin-bottom: 30px;
}

.decode__type {
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 16px 18px;
  font-size: 15px;
  color: var(--muted);
  background: #fff;
}
.decode__type strong {
  display: block;
  font-size: 16px;
  margin-bottom: 6px;
}
.decode__type[data-type="d"] strong { color: var(--d); }
.decode__type[data-type="i"] strong { color: var(--i); }
.decode__type[data-type="s"] strong { color: #0d9668; }
.decode__type[data-type="c"] strong { color: var(--c); }

.result__actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

/* ============ Responsive ============ */
@media (max-width: 1100px) {
  .disc-modal__tabs {
    justify-content: flex-start;
  }
}

@media (max-width: 900px) {
  .disc-grid3 { grid-template-columns: 1fr; gap: 14px; }
  .decode__grid { grid-template-columns: 1fr; }
}

@media (max-width: 640px) {
  .disc-modal__dialog {
    width: 100%;
    max-height: 100vh;
    max-height: 100dvh;
    height: 100vh;
    height: 100dvh;
    margin: 0;
    border-radius: 0;
  }
  .disc-modal__head { padding: 22px 18px 4px; }
  .disc-modal__tabs { padding: 12px 14px 4px; gap: 8px; }
  .disc-tab { padding: 11px 14px; font-size: 16px; }
  .disc-modal__body { padding: 10px 14px 20px; }
  .disc-foot { padding: 12px 14px 16px; }
  .disc-item { font-size: 16px; }
}

@media (max-width: 520px) {
  .disc-actions { flex-direction: column; align-items: stretch; }
  .disc-btn { width: 100%; padding: 14px 20px; }
  .result__actions .btn { width: 100%; text-align: center; }
  .bar { grid-template-columns: 40px 1fr 52px; gap: 10px; }
}
</style>
</head>
<body>

<!-- ================= Intro ================= -->
<main class="intro" id="intro">
  <div class="hero">
    <div class="hero__logo" aria-hidden="true">
      <span class="l-d">D</span><span class="l-i">I</span><span class="l-s">S</span><span class="l-c">C</span>
    </div>
    <h1>Бесплатный тест DISC <span>для руководителей</span></h1>
    <p class="hero__sub">Определите ваш управленческий стиль за 5 минут</p>

    <ul class="features">
      <li class="feature">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.6 13.4 12 4.8H4.8V12l8.6 8.6a2 2 0 0 0 2.8 0l4.4-4.4a2 2 0 0 0 0-2.8Z"/><circle cx="8.6" cy="8.6" r="1.3"/></svg>
        Бесплатный тест
      </li>
      <li class="feature">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3.2 2"/></svg>
        5 минут на прохождение
      </li>
      <li class="feature">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 20h18"/><path d="M6 20v-6"/><path d="M11 20V7"/><path d="M16 20v-9"/></svg>
        Результат сразу на экране
      </li>
    </ul>

    <button class="btn btn--primary hero__btn" type="button" id="startBtn">Пройти онлайн-тест</button>

    <p class="hero__note">24 блока · 8 шагов · ранжирование перетаскиванием</p>
  </div>
</main>

<!-- ================= Wizard ================= -->
<div class="disc-modal" id="wizardmodal" aria-hidden="true">
  <div class="disc-modal__overlay" data-disc-close></div>

  <div class="disc-modal__dialog" role="dialog" aria-modal="true" aria-labelledby="discTitle">
    <button class="disc-modal__close" type="button" data-disc-close aria-label="Закрыть">&times;</button>

    <div class="disc-modal__head">
      <h2 class="disc-modal__title" id="discTitle">Тестирование DISC</h2>
      <div class="disc-modal__sub">Помните - чем честнее вы с тестом, тем точнее результаты!</div>
      <div class="disc-modal__lead">Разместите блоки в порядке от наиболее похожего на вас до наименее похожего</div>
    </div>

    <div class="disc-modal__tabs" role="tablist" aria-label="Шаги">
      <button class="disc-tab is-active" type="button" role="tab" aria-selected="true" data-step-btn="0">Первый</button>
      <button class="disc-tab" type="button" role="tab" aria-selected="false" data-step-btn="1">Второй</button>
      <button class="disc-tab" type="button" role="tab" aria-selected="false" data-step-btn="2">Третий</button>
      <button class="disc-tab" type="button" role="tab" aria-selected="false" data-step-btn="3">Четвертый</button>
      <button class="disc-tab" type="button" role="tab" aria-selected="false" data-step-btn="4">Пятый</button>
      <button class="disc-tab" type="button" role="tab" aria-selected="false" data-step-btn="5">Шестой</button>
      <button class="disc-tab" type="button" role="tab" aria-selected="false" data-step-btn="6">Седьмой</button>
      <button class="disc-tab" type="button" role="tab" aria-selected="false" data-step-btn="7">Восьмой</button>
